from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    interval = int(parts[1])
    result = []

    def add_if_valid(candidate):
        if candidate >= start_date:
            result.append(candidate.isoformat())

    if kind == "DAILY":
        current = start_date
        while len(result) < count:
            result.append(current.isoformat())
            current += timedelta(days=interval)
        return result

    if kind == "WEEKLY":
        weekdays = parts[2].split(",")
        weekday_numbers = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                           "FR": 4, "SA": 5, "SU": 6}
        selected = sorted(weekday_numbers[day] for day in weekdays)
        week_start = start_date - timedelta(days=start_date.weekday())
        week_index = 0

        while len(result) < count:
            active_start = week_start + timedelta(weeks=week_index)
            for weekday in selected:
                candidate = active_start + timedelta(days=weekday)
                add_if_valid(candidate)
                if len(result) == count:
                    break
            week_index += interval
        return result

    if kind == "MONTHLY":
        if len(parts) == 3:
            day_spec = int(parts[2])
            month_index = 0
            while len(result) < count:
                year, month = divmod(
                    (start_date.year - 1) * 12 + (start_date.month - 1)
                    + month_index, 12
                )
                year += 1
                last_day = calendar.monthrange(year, month + 1)[1]
                day = last_day if day_spec == -1 else day_spec
                if day <= last_day:
                    add_if_valid(date(year, month + 1, day))
                month_index += interval
        else:
            occurrence = int(parts[2])
            weekday_numbers = {"MO": 0, "TU": 1, "WE": 2, "TH": 3,
                               "FR": 4, "SA": 5, "SU": 6}
            target_weekday = weekday_numbers[parts[3]]
            month_index = 0

            while len(result) < count:
                year, month = divmod(
                    (start_date.year - 1) * 12 + (start_date.month - 1)
                    + month_index, 12
                )
                year += 1
                month += 1
                first_weekday, days_in_month = calendar.monthrange(year, month)

                if occurrence == -1:
                    day = days_in_month - (
                        (calendar.weekday(year, month, days_in_month)
                         - target_weekday) % 7
                    )
                else:
                    day = 1 + ((target_weekday - first_weekday) % 7) + 7 * (occurrence - 1)

                if day <= days_in_month:
                    add_if_valid(date(year, month, day))
                month_index += interval
        return result

    if kind == "YEARLY":
        month, day = map(int, parts[2].split("-"))
        year = start_date.year
        while len(result) < count:
            try:
                candidate = date(year, month, day)
            except ValueError:
                candidate = None
            if candidate is not None:
                add_if_valid(candidate)
            year += interval

        return result

    return result
